def _get_cython_vals(
    self, values: np.ndarray, uses_mask: bool = False
) -> np.ndarray:
    """
    Cast numeric dtypes to float64 for functions that only support that.

    Parameters
    ----------
    values : np.ndarray

    Returns
    -------
    values : np.ndarray
    """
    how = self.how

    if how in ["median", "std", "sem", "skew", "kurt"]:
        # median only has a float64 implementation
        # non-numeric and complex cases are handled before we get here
        values = ensure_float64(values)

    elif values.dtype.kind in "iu":
        if how in ["var", "mean"] or (
            self.kind == "transform" and self.has_dropped_na and not uses_mask
        ):
            # has_dropped_na check need for test_null_group_str_transformer
            # result may still include NaN, so we have to cast
            values = ensure_float64(values)

        elif how in ["sum", "ohlc", "prod", "cumsum", "cumprod"]:
            # Avoid overflow during group op
            if values.dtype.kind == "i":
                values = ensure_int64(values)
            else:
                values = ensure_uint64(values)

    return values

def _get_output_shape(self, ngroups: int, values: np.ndarray) -> Shape:
    how = self.how
    kind = self.kind

    arity = self._cython_arity.get(how, 1)

    out_shape: Shape
    if how == "ohlc":
        out_shape = (ngroups, arity)
    elif arity > 1:
        raise NotImplementedError(
            "arity of more than 1 is not supported for the 'how' argument"
        )
    elif kind == "transform":
        out_shape = values.shape
    else:
        out_shape = (ngroups, *values.shape[1:])
    return out_shape

def _get_out_dtype(self, dtype: np.dtype) -> np.dtype:
    how = self.how

    if how == "rank":
        out_dtype = "float64"
    elif how in ["idxmin", "idxmax"]:
        # The Cython implementation only produces the row number; we'll take
        # from the index using this in post processing
        out_dtype = "intp"
    elif dtype.kind in "iufcb":
        out_dtype = f"{dtype.kind}{dtype.itemsize}"
    else:
        out_dtype = "object"
    return np.dtype(out_dtype)

